        self.goal_state = [[1, 2, 3], [4, 5, 6], [7, 8, 0]]

    def find_blank(self, state):
        for i in range(3):
            for j in range(3):
                if state[i][j] == 0:
                    return i, j

    def move(self, state, direction):
        x, y = self.find_blank(state)
        if direction == 'up' and x > 0:
            state[x][y], state[x-1][y] = state[x-1][y], state[x][y]
        elif direction == 'down' and x < 2:
            state[x][y], state[x+1][y] = state[x+1][y], state[x][y]
        elif direction == 'left' and y > 0:
            state[x][y], state[x][y-1] = state[x][y-1], state[x][y]
        elif direction == 'right' and y < 2:
            state[x][y], state[x][y+1] = state[x][y+1], state[x][y]
        return state

    def get_possible_moves(self, state):
        x, y = self.find_blank(state)
        possible_moves = []
        if x > 0:
            possible_moves.append('up')
        if x < 2:
            possible_moves.append('down')
        if y > 0:
            possible_moves.append('left')
        if y < 2:
            possible_moves.append('right')
        return possible_moves

    def solve(self):
        open_list = [(self.initial_state, [])]
        visited = set()
        while open_list:
            state, path = open_list.pop(0)
            if state == self.goal_state:
                return path
            if str(state) in visited:
                continue
            visited.add(str(state))
            for direction in self.get_possible_moves(state):
                new_state = self.move(list(map(list, state)), direction)
                open_list.append((new_state, path + [direction]))
        return []
