    """
    This is a class that implements methods for calculating indicators such as median, mode, correlation matrix, and Z-score in statistics.
    """

    def median(data):
        n = len(data)
        s = sorted(data)
        return (sum(s[n//2-1:n//2+1])/2.0, s[n//2])[n % 2] if n else None

    @staticmethod
    def mode(data):
        from collections import Counter
        data_dict = Counter(data)
        return [k for k, v in data_dict.items() if v == max(list(data_dict.values()))]

    @staticmethod
    def mean(data):
        return sum(data) / len(data)

    @staticmethod
    def correlation_matrix(data):
        n = len(data)
        if n == 0:
            return []
        m = len(data[0])
        if m == 0:
            return []
        means = [sum(x) / n for x in zip(*data)]
        deviations = [[x - mean for x in row] for row, mean in zip(data, means)]
        covariance = [[sum(i * j for i, j in zip(dev_row, dev_col)) / (n - 1) for dev_col in zip(*deviations)] for dev_row in deviations]
        std_devs = [math.sqrt(sum(x * x for x in row) / (n - 1)) for row in deviations]
        correlation = [[x / (y * z) for x, y, z in zip(cov, std_devs[i], std_devs[j])] for i, cov in enumerate(covariance)]
        return correlation

    @staticmethod
    def standard_deviation(data):
        n = len(data)
        mean = sum(data) / n
        variance = sum((x - mean) ** 2 for x in data) / n
        return math.sqrt(variance)

    @staticmethod
    def z_score(data):
        mean = sum(data) / len(data)
        std_dev = math.sqrt(sum((x - mean) ** 2 for x in data) / len(data))
        return [(x - mean) / std_dev for x in data]

    @staticmethod
    def correlation(x, y):
        """
        calculates the correlation of the given list.
        :param x: the given list, list.
        :param y: the given list, list.
        :return: the correlation of the given list, float.
        >>> statistics3 = Statistics3()
        >>> statistics3.correlation([1, 2, 3], [4, 5, 6])
        1.0
        """
        n = len(x)
        if n != len(y):
            raise ValueError("Both lists must have the same length")
        mean_x = sum(x) / n
        mean_y = sum(y) / n
        std_dev_x = math.sqrt(sum((xi - mean_x) ** 2 for xi in x) / n)
        std_dev_y = math.sqrt(sum((yi - mean_y) ** 2 for yi in y) / n)
        cov = sum((xi - mean_x) * (yi - mean_y) for xi, yi in zip(x, y)) / n
        return cov / (std_dev_x * std_dev_y)
