        else:
            return a * self.factorial(a-1)

    def taylor(self, x, n):
        result = 0
        for i in range(n):
            coef = (-1)**i
            num = x**(2*i+1)
            denom = self.factorial(2*i+1)
            result += ( coef ) * ( (num)/(denom) )
        return result

    def tan(self, x):
