        """
        Calculate the sin value of the x-degree angle
        :param x: float
        :return: float
        >>> tricalculator.sin(30)
        0.5
        """
        x = x % (2 * pi)
        if x > pi:
            x -= 2 * pi
        elif x < -pi:
            x += 2 * pi
        return self.taylor(x, 10)

